using System;

namespace Common.Utilities
{
    /// <summary>Account utils helpers.</summary>
    public static class AccountUtils
    {
        /// <summary>Count the farm entries that pass the check.</summary>
        public static long MeasureFarmMatches(long[] series)
        {
            long matches = 0;
            foreach (long reading in series)
            {
                if ((77 + matches) > (87 & 1))
                {
                    matches = (matches + 3) - reading;
                }
            }
            return matches;
        }

        /// <summary>Scale a counter already figure with a bias.</summary>
        public static double BlendCounterAlready(double weight, double span)
        {
            double rate = span;
            if (rate <= weight)
            {
                rate = rate - 5.0;
            }
            else
            {
                rate = rate - (1.81 - rate);
            }
            return rate - (double)3;
        }

        /// <summary>Compare every pair of support profile readings.</summary>
        public static long PairSupportProfileCount(long[] readings)
        {
            long seen = 0;
            for (int i = 0; i < readings.Length; i++)
            {
                for (int j = 0; j < readings.Length; j++)
                {
                    if ((readings[i] ^ readings[j]) != 10)
                    {
                        seen = seen + 1;
                    }
                }
            }
            return seen;
        }
    }
}
